sp_widget.client_script:
function(spUtil, $window, $timeout, $scope) {
  var c = this;

  c.sessionUser = {
    name:     ($scope.user && $scope.user.name)   || c.data.currentUser.name   || 'Reviewer',
    email:    c.data.currentUser.email            || '',
    sys_id:   ($scope.user && $scope.user.sys_id) || c.data.currentUser.sys_id || '',
    initials: ($window.NOW && $window.NOW.user_initials) ? $window.NOW.user_initials : c.data.currentUser.initials || 'R',
    loggedIn: $scope.user && $scope.user.logged_in
  };

  c.activeSection = 'home';
  c.sidebarOpen   = true;

  c.navTo = function(section) {
    c.activeSection = section;
    // reset proposal page when switching to proposals
    if (section === 'proposals') c.proposalPage = 1;
  };
  c.toggleSidebar = function() { c.sidebarOpen = !c.sidebarOpen; };

  c.profileOpen = false;
  c.toggleProfile = function($event) {
    $event.stopPropagation();
    c.profileOpen = !c.profileOpen;
  };
  c.logout = function() {
    $window.location.href = c.data.logoutUrl || '/login.do?logout=true';
  };
  c.goToProfile = function() {
    c.profileOpen = false;
    $window.location.href = c.data.profilePage || '?id=user_profile';
  };

  // ── Filters ───────────────────────────────────────────────
  c.searchText      = '';
  c.statusFilter    = '';
  c.categoryFilter  = '';
  c.programFilter   = '';

  // ── Pagination ────────────────────────────────────────────
  c.proposalPage    = 1;
  c.pageSize        = 12;  // 12 cards per page (4x3 grid)

  // Reset to page 1 whenever any filter changes
  $scope.$watchGroup(
    ['c.searchText', 'c.statusFilter', 'c.categoryFilter', 'c.programFilter'],
    function() { c.proposalPage = 1; }
  );

  // ── Unique category list for dropdown ─────────────────────
  c.categoryOptions = function() {
    var seen = {};
    var opts = [];
    (c.data.reviews || []).forEach(function(r) {
      if (r.status !== 'Review completed' && r.program_category && !seen[r.program_category]) {
        seen[r.program_category] = true;
        opts.push(r.program_category);
      }
    });
    return opts.sort();
  };

  // ── Unique program name list for dropdown ──────────────────
  c.programOptions = function() {
    var seen = {};
    var opts = [];
    (c.data.reviews || []).forEach(function(r) {
      if (r.status !== 'Review completed' && r.program && !seen[r.program]) {
        seen[r.program] = true;
        opts.push(r.program);
      }
    });
    return opts.sort();
  };

  // ── Full filtered list (no pagination) ────────────────────
  c.filteredProposals = function() {
    return (c.data.reviews || []).filter(function(r) {
      if (r.status === 'Review completed') return false;
      if (c.statusFilter   && r.status           !== c.statusFilter)   return false;
      if (c.categoryFilter && r.program_category !== c.categoryFilter) return false;
      if (c.programFilter  && r.program          !== c.programFilter)  return false;
      if (c.searchText) {
        var txt = c.searchText.toLowerCase();
        var num = (r.number           || '').toLowerCase();
        var prg = (r.program          || '').toLowerCase();
        var app = (r.applicant        || '').toLowerCase();
        var cat = (r.program_category || '').toLowerCase();
        if (num.indexOf(txt) === -1 &&
            prg.indexOf(txt) === -1 &&
            app.indexOf(txt) === -1 &&
            cat.indexOf(txt) === -1) return false;
      }
      return true;
    });
  };

  // ── Paginated slice shown on current page ─────────────────
  c.pagedProposals = function() {
    var all   = c.filteredProposals();
    var start = (c.proposalPage - 1) * c.pageSize;
    return all.slice(start, start + c.pageSize);
  };

  // ── Total pages ───────────────────────────────────────────
  c.totalPages = function() {
    return Math.ceil(c.filteredProposals().length / c.pageSize) || 1;
  };

  // ── Page numbers array for rendering buttons ──────────────
  c.pageNumbers = function() {
    var total  = c.totalPages();
    var current = c.proposalPage;
    var pages  = [];
    var start  = Math.max(1, current - 2);
    var end    = Math.min(total, current + 2);
    if (start > 1)     pages.push(1);
    if (start > 2)     pages.push('...');
    for (var i = start; i <= end; i++) pages.push(i);
    if (end < total - 1) pages.push('...');
    if (end < total)   pages.push(total);
    return pages;
  };

  c.goToPage = function(p) {
    if (p === '...' || p < 1 || p > c.totalPages()) return;
    c.proposalPage = p;
  };

  c.prevPage = function() { if (c.proposalPage > 1) c.proposalPage--; };
  c.nextPage = function() { if (c.proposalPage < c.totalPages()) c.proposalPage++; };

  // ── Completed reviews ─────────────────────────────────────
  c.completedReviews = function() {
    return (c.data.reviews || []).filter(function(r) {
      return r.status === 'Review completed';
    });
  };

  c.recentActivity = function() {
    return (c.data.reviews || []).slice(0, 5);
  };

  c.openRecord = function(rev) {
    if (!rev || !rev.sys_id) return;
    $window.location.href = '/review?id=review_proposal_detail_page&sys_id=' + rev.sys_id;
  };

  c.scoreWidth = function(score) {
    if (!score) return '0%';
    return Math.min(Math.round((parseInt(score) / 10) * 100), 100) + '%';
  };

  // ── Animated stats ────────────────────────────────────────
  c.animatedStats = { total: 0, inProgress: 0, completed: 0, onHold: 0 };

  function animateCount(key, target) {
    if (!target || target === 0) return;
    var step = Math.ceil(target / 30);
    var current = 0;
    var interval = setInterval(function() {
      current += step;
      if (current >= target) { current = target; clearInterval(interval); }
      c.animatedStats[key] = current;
      $timeout(function() {}, 0);
    }, 30);
  }

  $timeout(function() {
    var s = c.data.stats || {};
    animateCount('total',      s.total      || 0);
    animateCount('inProgress', s.inProgress || 0);
    animateCount('completed',  s.completed  || 0);
    animateCount('onHold',     s.onHold     || 0);
  }, 300);
}

sp_widget.css:
/* ═══════════════════════════════════════════════════
   SHELL & LAYOUT
═══════════════════════════════════════════════════ */
.rvd-shell {
  display: flex;
  min-height: 100vh;
  background: #f0f2f8;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  overflow: hidden;
  margin-top:4.5%;
}
/* ═══════════════════════════════════════════════════
   SIDEBAR PROFILE & DROPDOWN
═══════════════════════════════════════════════════ */
.rvd-sidebar__footer {
  padding: 12px 10px;
  border-top: 1px solid rgba(255,255,255,0.08);
  position: relative;
}

.rvd-profile-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.18s;
  user-select: none;
  position: relative;
}
/* Results meta bar */
.rvd-results-meta {
  display: flex;
  align-items: center;
  font-size: 13px;
  color: #6b7280;
  margin-bottom: 16px;
}
.rvd-results-meta a {
  color: #6366f1;
  text-decoration: none;
  cursor: pointer;
}
.rvd-results-meta a:hover { text-decoration: underline; }

/* Pagination */
.rvd-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 32px;
  padding-bottom: 24px;
}
.rvd-page-btn {
  min-width: 36px;
  height: 36px;
  padding: 0 10px;
  border: 1px solid #e5e7eb;
  background: #fff;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  color: #374151;
  cursor: pointer;
  transition: all 0.15s;
}
.rvd-page-btn:hover:not([disabled]):not(.rvd-page-btn--ellipsis) {
  background: #f3f4f6;
  border-color: #6366f1;
  color: #6366f1;
}
.rvd-page-btn--active {
  background: #6366f1 !important;
  border-color: #6366f1 !important;
  color: #fff !important;
}
.rvd-page-btn--ellipsis {
  border: none;
  background: transparent;
  cursor: default;
  color: #9ca3af;
}
.rvd-page-btn--nav { font-size: 12px; }
.rvd-page-btn[disabled] { opacity: 0.4; cursor: not-allowed; }

.rvd-profile-card:hover,
.rvd-profile-card--open {
  background: rgba(255,255,255,0.10);
}

.rvd-profile-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
  letter-spacing: 0.5px;
  border: 2px solid rgba(255,255,255,0.2);
}

.rvd-profile-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
  overflow: hidden;
  transition: opacity 0.2s, width 0.3s;
}

.rvd-sidebar--collapsed .rvd-profile-details,
.rvd-sidebar--collapsed .rvd-profile-caret {
  opacity: 0;
  pointer-events: none;
  width: 0;
}

.rvd-profile-name {
  font-size: 12.5px;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rvd-profile-role {
  font-size: 11px;
  color: rgba(255,255,255,0.45);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rvd-profile-caret {
  font-size: 10px;
  color: rgba(255,255,255,0.4);
  flex-shrink: 0;
  transition: transform 0.2s;
}

/* Dropdown */
.rvd-profile-dropdown {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 10px;
  right: 10px;
  background: #fff;
  border-radius: 12px;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.18), 0 8px 24px rgba(0,0,0,0.12);
  overflow: hidden;
  z-index: 200;
  animation: rvdDropUp 0.18s cubic-bezier(.4,0,.2,1);
}

@keyframes rvdDropUp {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0);   }
}

.rvd-dropdown-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 14px 12px;
  background: #fafafa;
}

.rvd-dropdown-avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

.rvd-dropdown-name {
  font-size: 13px;
  font-weight: 700;
  color: #111827;
}

.rvd-dropdown-email {
  font-size: 11.5px;
  color: #9ca3af;
  margin-top: 1px;
}

.rvd-dropdown-divider {
  height: 1px;
  background: #f3f4f6;
}

.rvd-dropdown-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px;
  background: none;
  border: none;
  font-size: 13px;
  color: #374151;
  cursor: pointer;
  text-align: left;
  transition: background 0.12s, color 0.12s;
  font-weight: 500;
}

.rvd-dropdown-item i {
  font-size: 14px;
  color: #9ca3af;
  width: 18px;
  text-align: center;
}

.rvd-dropdown-item:hover {
  background: #f9fafb;
  color: #111827;
}

.rvd-dropdown-item--danger {
  color: #ef4444;
}

.rvd-dropdown-item--danger i {
  color: #ef4444;
}

.rvd-dropdown-item--danger:hover {
  background: #fef2f2;
  color: #dc2626;
}

/* ═══════════════════════════════════════════════════
   SIDEBAR
═══════════════════════════════════════════════════ */
.rvd-sidebar {
  width: 240px;
  min-width: 240px;
  background: linear-gradient(180deg, #1e1b4b 0%, #312e81 60%, #3730a3 100%);
  display: flex;
  flex-direction: column;
  padding: 0;
  transition: width 0.3s cubic-bezier(.4,0,.2,1),
              min-width 0.3s cubic-bezier(.4,0,.2,1);
  overflow: hidden;
  box-shadow: 4px 0 24px rgba(49,46,129,0.18);
  z-index: 100;
}

.rvd-sidebar--collapsed {
  width: 64px;
  min-width: 64px;
}

.rvd-sidebar--collapsed .rvd-brand-text,
.rvd-sidebar--collapsed .rvd-nav__label,
.rvd-sidebar--collapsed .rvd-nav__badge,
.rvd-sidebar--collapsed .rvd-reviewer-info {
  opacity: 0;
  pointer-events: none;
  width: 0;
  overflow: hidden;
}

.rvd-sidebar__brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 24px 20px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.rvd-brand-icon {
  width: 36px;
  height: 36px;
  background: rgba(255,255,255,0.15);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 16px;
  flex-shrink: 0;
}

.rvd-brand-text {
  font-size: 16px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 0.3px;
  white-space: nowrap;
  transition: opacity 0.2s, width 0.3s;
}

/* Nav */
.rvd-nav {
  flex: 1;
  padding: 16px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.rvd-nav__item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 10px;
  color: rgba(255,255,255,0.6);
  cursor: pointer;
  transition: background 0.18s, color 0.18s, transform 0.15s;
  text-decoration: none;
  position: relative;
  white-space: nowrap;
}

.rvd-nav__item:hover {
  background: rgba(255,255,255,0.08);
  color: #fff;
  transform: translateX(2px);
}

.rvd-nav__item--active {
  background: rgba(255,255,255,0.15);
  color: #fff;
  font-weight: 600;
}

.rvd-nav__item--active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 3px;
  background: #818cf8;
  border-radius: 0 3px 3px 0;
}

.rvd-nav__icon {
  font-size: 16px;
  width: 20px;
  text-align: center;
  flex-shrink: 0;
}

.rvd-nav__label {
  font-size: 13.5px;
  transition: opacity 0.2s, width 0.3s;
}

.rvd-nav__badge {
  margin-left: auto;
  background: #f59e0b;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 999px;
  transition: opacity 0.2s;
}

.rvd-nav__badge--green {
  background: #10b981;
}

/* Sidebar footer */
.rvd-sidebar__footer {
  padding: 16px 12px;
  border-top: 1px solid rgba(255,255,255,0.08);
}

.rvd-reviewer-pill {
  display: flex;
  align-items: center;
  gap: 10px;
}

.rvd-reviewer-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 14px;
  flex-shrink: 0;
}

.rvd-reviewer-info {
  display: flex;
  flex-direction: column;
  transition: opacity 0.2s, width 0.3s;
  overflow: hidden;
}

.rvd-reviewer-name {
  font-size: 12.5px;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
}

.rvd-reviewer-role {
  font-size: 11px;
  color: rgba(255,255,255,0.5);
  white-space: nowrap;
}

/* ═══════════════════════════════════════════════════
   MAIN AREA
═══════════════════════════════════════════════════ */
.rvd-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: all 0.3s;
}

/* Topbar */
.rvd-topbar {
  height: 60px;
  background: #fff;
  border-bottom: 1px solid #e5e7eb;
  display: flex;
  align-items: center;
  padding: 0 24px;
  gap: 16px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
  flex-shrink: 0;
}

.rvd-topbar__toggle {
  background: none;
  border: none;
  font-size: 18px;
  color: #6b7280;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: background 0.15s, color 0.15s;
}

.rvd-topbar__toggle:hover {
  background: #f3f4f6;
  color: #111827;
}

.rvd-topbar__breadcrumb {
  font-size: 15px;
  font-weight: 600;
  color: #111827;
  flex: 1;
}

.rvd-topbar__right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.rvd-topbar__date {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  color: #9ca3af;
}

/* Content area */
.rvd-content {
  flex: 1;
  overflow-y: auto;
  padding: 28px 28px 40px;
}

/* ═══════════════════════════════════════════════════
   WELCOME BANNER
═══════════════════════════════════════════════════ */
.rvd-welcome-banner {
  background: linear-gradient(135deg, #3730a3 0%, #6d28d9 100%);
  border-radius: 16px;
  padding: 28px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
  overflow: hidden;
  position: relative;
}

.rvd-welcome-banner::before {
  content: '';
  position: absolute;
  top: -40px;
  right: 80px;
  width: 160px;
  height: 160px;
  background: rgba(255,255,255,0.05);
  border-radius: 50%;
}

.rvd-welcome-banner::after {
  content: '';
  position: absolute;
  bottom: -30px;
  right: 40px;
  width: 100px;
  height: 100px;
  background: rgba(255,255,255,0.04);
  border-radius: 50%;
}

.rvd-welcome-title {
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  margin: 0 0 8px;
}

.rvd-welcome-sub {
  font-size: 13.5px;
  color: rgba(255,255,255,0.7);
  max-width: 480px;
  margin: 0;
  line-height: 1.6;
}

.rvd-welcome-illustration {
  font-size: 56px;
  color: rgba(255,255,255,0.12);
  flex-shrink: 0;
  z-index: 1;
}

/* ═══════════════════════════════════════════════════
   STAT CARDS
═══════════════════════════════════════════════════ */
.rvd-stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

.rvd-stat-card {
  border-radius: 14px;
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: default;
}

.rvd-stat-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(0,0,0,0.12);
}

.rvd-stat-card--blue  { background: linear-gradient(135deg,#eff6ff,#dbeafe); }
.rvd-stat-card--amber { background: linear-gradient(135deg,#fffbeb,#fef3c7); }
.rvd-stat-card--green { background: linear-gradient(135deg,#ecfdf5,#d1fae5); }
.rvd-stat-card--red   { background: linear-gradient(135deg,#fef2f2,#fee2e2); }

.rvd-stat-card__icon {
  font-size: 22px;
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.rvd-stat-card--blue  .rvd-stat-card__icon { background: #dbeafe; color: #1d4ed8; }
.rvd-stat-card--amber .rvd-stat-card__icon { background: #fde68a; color: #b45309; }
.rvd-stat-card--green .rvd-stat-card__icon { background: #a7f3d0; color: #047857; }
.rvd-stat-card--red   .rvd-stat-card__icon { background: #fecaca; color: #b91c1c; }

.rvd-stat-card__body {
  display: flex;
  flex-direction: column;
}

.rvd-stat-card__num {
  font-size: 30px;
  font-weight: 800;
  line-height: 1;
  margin-bottom: 4px;
}

.rvd-stat-card--blue  .rvd-stat-card__num { color: #1e40af; }
.rvd-stat-card--amber .rvd-stat-card__num { color: #92400e; }
.rvd-stat-card--green .rvd-stat-card__num { color: #065f46; }
.rvd-stat-card--red   .rvd-stat-card__num { color: #991b1b; }

.rvd-stat-card__label {
  font-size: 12px;
  font-weight: 500;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.rvd-stat-card__glow {
  position: absolute;
  right: -10px;
  top: -10px;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  opacity: 0.15;
}

.rvd-stat-card--blue  .rvd-stat-card__glow { background: #3b82f6; }
.rvd-stat-card--amber .rvd-stat-card__glow { background: #f59e0b; }
.rvd-stat-card--green .rvd-stat-card__glow { background: #10b981; }
.rvd-stat-card--red   .rvd-stat-card__glow { background: #ef4444; }

/* ═══════════════════════════════════════════════════
   HOME PANELS
═══════════════════════════════════════════════════ */
.rvd-home-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.rvd-panel {
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 1px 6px rgba(0,0,0,0.06);
  overflow: hidden;
}

.rvd-panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid #f3f4f6;
}

.rvd-panel__title {
  font-size: 14px;
  font-weight: 700;
  color: #111827;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.rvd-panel__title i {
  color: #6366f1;
}

.rvd-panel__link {
  background: none;
  border: none;
  font-size: 12.5px;
  color: #6366f1;
  cursor: pointer;
  font-weight: 500;
  transition: color 0.15s;
}

.rvd-panel__link:hover { color: #4f46e5; }

.rvd-panel__body {
  padding: 12px 20px 20px;
}

/* Activity list */
.rvd-activity-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid #f9fafb;
  cursor: pointer;
  transition: background 0.12s;
  border-radius: 6px;
}

.rvd-activity-item:hover { background: #fafafa; }
.rvd-activity-item:last-child { border-bottom: none; }

.rvd-activity-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.rvd-dot--amber { background: #f59e0b; }
.rvd-dot--green { background: #10b981; }
.rvd-dot--red   { background: #ef4444; }

.rvd-activity-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.rvd-activity-num {
  font-size: 13px;
  font-weight: 700;
  color: #111827;
}

.rvd-activity-prog {
  font-size: 11.5px;
  color: #9ca3af;
}

.rvd-activity-status {
  font-size: 10.5px;
  padding: 3px 8px;
  border-radius: 999px;
  font-weight: 600;
  white-space: nowrap;
}

/* Progress bars */
.rvd-progress-item {
  margin-bottom: 16px;
}

.rvd-progress-meta {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: #6b7280;
  margin-bottom: 5px;
  font-weight: 500;
}

.rvd-progress-track {
  height: 8px;
  background: #f3f4f6;
  border-radius: 999px;
  overflow: hidden;
}

.rvd-progress-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.8s cubic-bezier(.4,0,.2,1);
}

.rvd-progress-fill--amber { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
.rvd-progress-fill--green { background: linear-gradient(90deg, #10b981, #34d399); }
.rvd-progress-fill--red   { background: linear-gradient(90deg, #ef4444, #f87171); }

/* Donut bar */
.rvd-donut-row {
  display: flex;
  height: 12px;
  border-radius: 999px;
  overflow: hidden;
  margin-top: 20px;
  gap: 2px;
}

.rvd-donut-segment {
  height: 100%;
  border-radius: 999px;
  transition: flex 0.8s cubic-bezier(.4,0,.2,1);
}

.rvd-legend-row {
  display: flex;
  gap: 16px;
  margin-top: 10px;
}

.rvd-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  color: #6b7280;
}

.rvd-legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}

/* ═══════════════════════════════════════════════════
   SECTION HEADER
═══════════════════════════════════════════════════ */
.rvd-section-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}

.rvd-section-title {
  font-size: 20px;
  font-weight: 800;
  color: #111827;
  margin: 0 0 4px;
}

.rvd-section-sub {
  font-size: 13px;
  color: #9ca3af;
  margin: 0;
  max-width: 520px;
  line-height: 1.5;
}

.rvd-completed-badge {
  background: #d1fae5;
  color: #065f46;
  font-size: 13px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

/* ═══════════════════════════════════════════════════
   FILTER BAR
═══════════════════════════════════════════════════ */
.rvd-filter-bar {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.rvd-filter-search {
  flex: 1;
  min-width: 220px;
  position: relative;
}

.rvd-filter-search__icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #9ca3af;
  font-size: 13px;
}

.rvd-filter-search__input {
  width: 100%;
  height: 40px;
  padding: 0 14px 0 36px;
  border: 1.5px solid #e5e7eb;
  border-radius: 10px;
  font-size: 13.5px;
  color: #111827;
  background: #fff;
  transition: border-color 0.18s, box-shadow 0.18s;
  outline: none;
  box-sizing: border-box;
}

.rvd-filter-search__input:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99,102,241,0.12);
}

.rvd-filter-select {
  height: 40px;
  padding: 0 14px;
  border: 1.5px solid #e5e7eb;
  border-radius: 10px;
  font-size: 13.5px;
  color: #374151;
  background: #fff;
  cursor: pointer;
  outline: none;
  transition: border-color 0.18s;
}

.rvd-filter-select:focus {
  border-color: #6366f1;
}

/* ═══════════════════════════════════════════════════
   PROPOSAL CARDS
═══════════════════════════════════════════════════ */
.rvd-proposal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 18px;
}

.rvd-proposal-card {
  background: #fff;
  border-radius: 14px;
  border: 1.5px solid #f3f4f6;
  padding: 18px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 14px;
  transition: transform 0.2s cubic-bezier(.4,0,.2,1),
              box-shadow 0.2s,
              border-color 0.2s;
  position: relative;
  overflow: hidden;
}

.rvd-proposal-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #6366f1, #8b5cf6);
  opacity: 0;
  transition: opacity 0.2s;
}

.rvd-proposal-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(99,102,241,0.12);
  border-color: #e0e7ff;
}

.rvd-proposal-card:hover::before {
  opacity: 1;
}

.rvd-proposal-card__num-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}

.rvd-proposal-num {
  font-size: 12px;
  font-weight: 700;
  color: #6366f1;
  background: #eef2ff;
  padding: 3px 10px;
  border-radius: 6px;
  letter-spacing: 0.3px;
}

.rvd-proposal-program {
  font-size: 14.5px;
  font-weight: 700;
  color: #111827;
  margin: 0 0 4px;
  line-height: 1.4;
}

.rvd-proposal-applicant {
  font-size: 12.5px;
  color: #9ca3af;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 5px;
}

.rvd-proposal-card__mid {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: #fafafa;
  border-radius: 10px;
  padding: 12px;
}

.rvd-info-pair {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12.5px;
}

.rvd-info-pair__label {
  color: #9ca3af;
  font-weight: 500;
}

.rvd-info-pair__val {
  color: #374151;
  font-weight: 600;
}

.rvd-score-val {
  color: #6366f1 !important;
}

/* Score bar */
.rvd-proposal-card__score-bar {
  display: flex;
  align-items: center;
  gap: 10px;
}

.rvd-score-track {
  flex: 1;
  height: 6px;
  background: #f3f4f6;
  border-radius: 999px;
  overflow: hidden;
}

.rvd-score-fill {
  height: 100%;
  background: linear-gradient(90deg, #6366f1, #8b5cf6);
  border-radius: 999px;
  transition: width 0.6s cubic-bezier(.4,0,.2,1);
}

.rvd-score-pct {
  font-size: 11px;
  color: #6b7280;
  font-weight: 600;
  white-space: nowrap;
}

/* Card footer */
.rvd-proposal-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px solid #f3f4f6;
}

.rvd-group-tag {
  font-size: 11.5px;
  color: #9ca3af;
  display: flex;
  align-items: center;
  gap: 5px;
}

.rvd-open-link {
  font-size: 12px;
  font-weight: 600;
  color: #6366f1;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: gap 0.15s;
}

.rvd-proposal-card:hover .rvd-open-link {
  gap: 8px;
}

/* ═══════════════════════════════════════════════════
   CHIPS
═══════════════════════════════════════════════════ */
.rvd-chip {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.rvd-chip--amber { background: #fef3c7; color: #b45309; }
.rvd-chip--green { background: #d1fae5; color: #065f46; }
.rvd-chip--red   { background: #fee2e2; color: #991b1b; }
.rvd-chip--blue  { background: #dbeafe; color: #1d4ed8; }

/* ═══════════════════════════════════════════════════
   COMPLETED TABLE
═══════════════════════════════════════════════════ */
.rvd-completed-table-wrap {
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 1px 6px rgba(0,0,0,0.06);
  overflow: hidden;
}

.rvd-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13.5px;
}

.rvd-table thead th {
  padding: 14px 18px;
  text-align: left;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #9ca3af;
  background: #fafafa;
  border-bottom: 1px solid #f3f4f6;
}

.rvd-table-row td {
  padding: 14px 18px;
  border-bottom: 1px solid #f9fafb;
  color: #374151;
  vertical-align: middle;
}

.rvd-table-row:last-child td {
  border-bottom: none;
}

.rvd-table-row {
  transition: background 0.12s;
}

.rvd-table-row:hover {
  background: #fafafa;
}

.rvd-score-pill {
  background: #eef2ff;
  color: #4f46e5;
  padding: 3px 10px;
  border-radius: 6px;
  font-weight: 700;
  font-size: 12.5px;
}

.rvd-muted {
  color: #d1d5db;
}

.rvd-tbl-btn {
  background: none;
  border: 1.5px solid #e5e7eb;
  padding: 5px 12px;
  border-radius: 7px;
  font-size: 12px;
  color: #6366f1;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 5px;
  font-weight: 600;
  transition: background 0.15s, border-color 0.15s;
}

.rvd-tbl-btn:hover {
  background: #eef2ff;
  border-color: #c7d2fe;
}

/* ═══════════════════════════════════════════════════
   EMPTY STATE
═══════════════════════════════════════════════════ */
.rvd-empty-state {
  text-align: center;
  padding: 60px 20px;
  color: #9ca3af;
}

.rvd-empty-state i {
  font-size: 48px;
  margin-bottom: 16px;
  display: block;
  color: #d1d5db;
}

.rvd-empty-state h3 {
  font-size: 16px;
  font-weight: 700;
  color: #374151;
  margin: 0 0 8px;
}

.rvd-empty-state p {
  font-size: 13.5px;
  max-width: 360px;
  margin: 0 auto;
  line-height: 1.6;
}

.rvd-empty-state--sm {
  padding: 24px 16px;
}

.rvd-empty-state--sm i {
  font-size: 28px;
  margin-bottom: 8px;
}

/* ═══════════════════════════════════════════════════
   NO ACCESS
═══════════════════════════════════════════════════ */
.rvd-no-access {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 50vh;
  text-align: center;
  color: #9ca3af;
  padding: 40px;
}

.rvd-no-access i {
  font-size: 52px;
  color: #ef4444;
  margin-bottom: 20px;
}

.rvd-no-access h3 {
  font-size: 18px;
  font-weight: 700;
  color: #374151;
  margin: 0 0 8px;
}

.rvd-no-access p {
  font-size: 13.5px;
  max-width: 360px;
  line-height: 1.6;
}

/* ═══════════════════════════════════════════════════
   RESPONSIVE
═══════════════════════════════════════════════════ */
@media (max-width: 900px) {
  .rvd-stats-row {
    grid-template-columns: 1fr 1fr;
  }
  .rvd-home-grid {
    grid-template-columns: 1fr;
  }
  .rvd-sidebar {
    width: 64px;
    min-width: 64px;
  }
  .rvd-brand-text,
  .rvd-nav__label,
  .rvd-nav__badge,
  .rvd-reviewer-info {
    display: none;
  }
}

@media (max-width: 600px) {
  .rvd-stats-row {
    grid-template-columns: 1fr;
  }
  .rvd-content {
    padding: 16px;
  }
  .rvd-welcome-banner {
    padding: 20px;
  }
  .rvd-welcome-illustration {
    display: none;
  }
  .rvd-proposal-grid {
    grid-template-columns: 1fr;
  }
}

sp_widget.script:
(function() {

  // ── Logged-in user info for sidebar profile ──────────────
  var userGr = new GlideRecord('sys_user');
  if (userGr.get(gs.getUserID())) {
    data.currentUser = {
      sys_id:     userGr.getUniqueValue(),
      name:       userGr.getDisplayValue('name')  || 'Reviewer',
      first_name: userGr.getValue('first_name')   || '',
      last_name:  userGr.getValue('last_name')    || '',
      email:      userGr.getValue('email')        || '',
      title:      userGr.getValue('title')        || 'Grant Reviewer',
      initials:   (userGr.getValue('first_name') || 'R').charAt(0).toUpperCase() +
                  (userGr.getValue('last_name')  || '').charAt(0).toUpperCase()
    };
  } else {
    data.currentUser = {
      name: 'Guest', first_name: '', last_name: '',
      email: '', title: '', initials: 'G', sys_id: ''
    };
  }

  // ── Portal logout URL ─────────────────────────────────────
  var portalRecord = $sp.getPortalRecord();
  data.logoutUrl   = '/login.do?logout=true';
  data.profilePage = '?id=user_profile';

  // ── Access control ────────────────────────────────────────
  data.canRead = true;
  data.reviews = [];
  data.stats   = { total: 0, inProgress: 0, completed: 0, onHold: 0 };

  var userId = gs.getUserID();

  // ── Get groups for current user ───────────────────────────
  var groups = [];
  var grMem  = new GlideRecord('sys_user_grmember');
  grMem.addQuery('user', userId);
  grMem.query();
  while (grMem.next()) {
    groups.push(grMem.getValue('group'));
  }

  if (groups.length === 0) return;

  // ── Load reviews: active (assigned to group) OR completed (group was a reviewer) ──
  var gr = new GlideRecord('x_enno_gatenow_grant_review');

  var qc = gr.addQuery('assignment_group', 'IN', groups.join(','));

  for (var i = 0; i < groups.length; i++) {
    var orCond = qc.addOrCondition('status', 'Review completed');
    orCond.addCondition('reviewer', 'CONTAINS', groups[i]);
  }

  gr.orderBy('number');
  gr.query();

  while (gr.next()) {
    var status = gr.getDisplayValue('status');
    data.stats.total++;
    if (status === 'Review in progress')    data.stats.inProgress++;
    else if (status === 'Review completed') data.stats.completed++;
    else if (status === 'Escalated')        data.stats.onHold++;

    // ── Look up program_name + number from the program reference field ──
    var programName     = '';
    var programCategory = '';
    var programNumber   = '';
    var programSysId    = gr.getValue('program');
    if (programSysId) {
      var progGr = new GlideRecord('x_enno_gatenow_grant_program');
      if (progGr.get(programSysId)) {
        programName     = progGr.getDisplayValue('program_name') || '';
        programCategory = progGr.getDisplayValue('category')     || '';
        programNumber   = progGr.getValue('number')              || '';
      }
    }

    // ── Look up applicant name + number from the applicant reference field ──
    var applicantName   = '';
    var applicantNumber = '';
    var applicantSysId  = gr.getValue('applicant');
    if (applicantSysId) {
      var appGr = new GlideRecord('x_enno_gatenow_service_applicants');
      if (appGr.get(applicantSysId)) {
        applicantName   = ((appGr.getValue('first_name') || '') + ' ' +
                           (appGr.getValue('last_name')  || '')).trim();
        applicantNumber = appGr.getValue('number') || '';
      }
    }

    data.reviews.push({
      sys_id:            gr.getUniqueValue(),
      number:            gr.getValue('number')                  || '',
      status:            status,
      assignment_group:  gr.getDisplayValue('assignment_group') || '',
      score:             gr.getValue('score')                   || '',
      applicant:         applicantName,
      applicant_number:  applicantNumber,        
      program:           programName,
      program_number:    programNumber,          
      program_category:  programCategory,
      reviewer:          gr.getDisplayValue('reviewer')         || '',
      decision_type:     gr.getDisplayValue('decision_type')    || ''
    });

  }

  // ── Save review ───────────────────────────────────────────
  if (input && input.action == 'save_review' && input.review_sys_id) {
    var reviewId = String(input.review_sys_id);
    var form     = input.form || {};

    var grUpdate = new GlideRecord('x_enno_gatenow_grant_review');
    if (grUpdate.get(reviewId)) {

      if (groups.indexOf(grUpdate.getValue('assignment_group')) == -1) {
        data.success = false;
        data.error   = 'You are not allowed to update this review.';
        return;
      }

      if (form.decision_type)         grUpdate.setValue('decision_type',  form.decision_type);
      if (form.status)                grUpdate.setValue('status',         form.status);
      if (!gs.nil(form.score))        grUpdate.setValue('score',          form.score);
      if (!gs.nil(form.review_notes)) grUpdate.setValue('work_notes',     form.review_notes);

      grUpdate.update();
      data.success = true;

    } else {
      data.success = false;
      data.error   = 'Review record not found.';
    }
  }

})();
